  box-sizing: border-box;
  width: 200px;
  padding: 20px;
  border: 5px solid black;
  /* actual width stays 200px, content shrinks to fit */
}

div {
  padding: 15px;  /* space inside, between content and border */
  margin: 20px;   /* space outside, between this element and others */
  background-color: lightblue; /* fills content + padding, not margin */
}

/* Method 1: Flexbox (most common) */
.parent {
  display: flex;
  justify-content: center; /* horizontal */
  align-items: center;     /* vertical */
  height: 100vh;
}

/* Method 2: Grid (shortest) */
.parent {
  display: grid;
  place-items: center;
  height: 100vh;
}

/* Method 3: Margin auto (horizontal only) */
.child {
  width: 200px;
  margin: 0 auto;
}

/* Method 4: Absolute positioning */
.child {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

/* width: auto - safely fits within parent, accounting for margin/padding */
.box1 {
  width: auto;
  padding: 20px;
  margin: 10px;
}

/* width: 100% - can overflow parent if padding/border added without border-box */
.box2 {
  width: 100%;
  padding: 20px; /* this adds extra width, causing overflow */
  box-sizing: border-box; /* fix: prevents overflow */
}

/* Common best practice: apply to all elements */
*, *::before, *::after {
  box-sizing: border-box;
}

.box {
  width: 300px;
  padding: 20px;
  border: 10px solid gray;
  /* Total width stays exactly 300px, content area shrinks automatically */
}
